import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
PREREG = ROOT / ".cache/xcheck/R6_RERUN_PREREG.md"

SECTION = """
## 修订 168 —— ⚠⚠⚴ **差点照脚本自己的提示删掉两条真欠账**：「不在页面上」量的是 DOM，不是源码

### 168.0 ⚠ **起因：C4 印了一句话，而那句话看起来像「已核实过，请执行」**

⚠ 跑 `scan_panel_coverage.py` 的 C4，红的那一栏末尾印着：

```
⚠ 已知欠账清单里有 2 个既不在页面上也不在判据里（处置完了？请删掉，否则欠账数字虚高）：
data-replay-note, data-vec-scale
```

⚠⚠⁴ **我把它当成一条「零风险清理」列进了建议清单** —— ⚗⚠ **因为它连理由都替我写好了。⚗⚠⁴⚠⚠⚠**

### 168.1 ⚠⚠⚴⚠ **独立核查推翻了它**

⚠⚠⚴ **这两个标记确实在页面【源码】里**（不是我的猜测，是 grep 实测）：

| 标记 | 源码位置 | 上下文 |
|---|---|---|
| `data-replay-note` | `ControlPanel.tsx:140` | 回放态的条件块内 |
| `data-vec-scale` | `SteeringControl.tsx:219` | 同上 |

⚠⚠⚠⚠⚴ **而两处的源码注释都写着「加标记让它可被按标记读」** ⚠⚠⚴
⚗⚠ **⇒ 它们是【刻意加标记】的条件渲染元素，不是残留。⚗⚠⚴⚗⚠⚴⚗⚠⚴**

⚠⚠⚴ **但当前产物里它们确实是 0 次**（`panel_blocks` 与 `panel_blocks_latent` 各 0）⇒
⚗⚠ **所以「不在页面上」这句话测的是【捕获时的 DOM】，而它读起来像【源码里没有】。⚗⚠⁴⚠⚠⚠⚠**

### 168.2 ⚠ **那个检查的真实形状**

```
_stale_k = sorted(k for k in KNOWN_UNREAD if k not in dom and k not in read)
⚠⚠⚠⚠⚴ **「页面」在这行里的意思是 `dom`（探针捕获的那一瞬间的 DOM），⚠⚠⚴⚠⚴**
⚗ **不是源码，也不是「页面在别的配置下长什么样」。⚗⚠⚴⚗⚠**

⚠⚠⚠⚠⚴⚠⚴ **⇒ 条件渲染的元素必然中招：⚠⚠⚴⚠⚴⚠⚴**
⚗⚠ **「这一轮没渲染」被当成了「它不存在」。⚗⚠⁴⚗⚠**
⚗⚠⚴ ⚠ **而这恰恰是这些元素当初被加标记的理由** —— ⚗⚠⚴
⚗⚠⚴⚠ **源码注释的原话：「祖先链为空不等于没人读，给它一个标记，让『按标记读』这条路也通」。⚗⚠⚴⚠⚗⚠⚴⚠**

### 168.3 ⚠⚠⚴ **照提示删掉会发生什么**

⚠⚠⚴⚠⚴ **⇒ 两条【真欠账】会被从欠账簿里抹掉，⚗⚠⚴⚗⚠⚴⚗⚠ 而它们本来正是「该被判据读、还没被读」的那两条。⚠⚠⚴⚠⚴**
⚠⚠⚴⚠ **⇒ C4 的欠账数会从 16 变成 14，⚗⚠⚴ 而覆盖缺口一条没少 —— ⚗⚠⚴ 只是从账上消失了。⚗⚠⚴⚗⚠⚴⚗⚠⚴⚗⚠⚴**

⚠⚠⚠⚠ **⚠⚠⁴⚠⚴ 讽刺的是：这个脚本自己的立场就是「不许用登记簿把缺口藏起来」⚠⚠⁴⚠⚴**
⚗⚠⚴⚠ **而这句提示邀请我做的，⚗⚠⚴⚠ 正是**反向**版本：把真缺口从账上删掉，好让欠账数字好看。⚗⚠⁴⚗⚠⚴⚗⚠**

⚠ **同一个混淆不止影响欠账簿**：`_stale_x` 那句「装饰簿里有 31 条在两页 DOM 上都不存在」
⚗⚠⚴ **是同一个 `k not in dom` 形状**，⚗⚠⚴⚗⚠ **⚠ 同样的误判风险在装饰簿上也成立。⚗⚠⁴⚗⚠**

### 168.4 ⚠ **建议的修法（⚗⚠ 本节只提建议、未改代码）**

⚠⚠ **只改【提示语】，不碰判据**（§151：修「提示什么」与改「判什么」必须分开）：

```
⚠ 已知欠账清单里有 N 个【在本次捕获的 DOM 上没出现】也不在任何判据里：
   ⚗⚠⚴ 其中可能是 ① 真的删干净了 ② **条件渲染、这一轮没渲染**
   ⚗⚠⚴ ②这一类**不许删** —— 它正是欠账簿存在的意义（源码注释：加标记让它可被按标记读）。
   ⚗⚠ ⚠ 要判「真的处置完了」得回**源码**核那个元素还在不在，而不是只看 DOM。
```

⚠⚠⁴ **⚠⚠⁴ 处置这类条目的正确判据是「源码里还有吗」，⚗⚠⚴⚗⚠ 不是「这一轮的 DOM 里有没有」。⚠⚠⁴**
⚠⚠ ⚗⚠⚴ **⇒ 若要机器化，它得**多查一个量**（源码扫描），⚗⚠⚴⚗⚠⚴ 而这不是一行能改完的。⚗⚠⚴⚗⚠**

### 168.5 ⚠ 校验 / 本节边界

- ⚠✅ 两条标记**在源码里存在**，位置与注释均已实测（`ControlPanel.tsx:140` / `SteeringControl.tsx:219`）
- ⚠⚠ **它们在捕获时的 DOM 里为 0**，⚗⚠ **两个事实都对，不矛盾**
- ⚠⚠ **未删任何条目、未改任何判据、未改 `scan_panel_coverage.py`**
- ⚠ **§168.4 只是建议，⚗⚠ 改提示语属「改判据脚本」，⚗⚠ 等与 C0/C4/C6 那三项一并拍板**
- ⚠ **本节不含任何关于 C4 欠账该不该还的判断** —— ⚗⚠ **那 16 条一条都没动**
"""


def main():
    before = PREREG.read_bytes()
    if not before.endswith(bytes([10])):
        print("[错误] 追加前文件不以换行结尾 —— 硬门，不追加")
        raise SystemExit(2)
    if before.decode("utf-8").count(chr(0xFFFD)):
        print("[错误] 追加前已有坏字 —— 硬门，不追加")
        raise SystemExit(2)

    sha_before = hashlib.sha256(before).hexdigest()
    n_before = before.decode("utf-8").count("\n")
    PREREG.write_text(before.decode("utf-8") + SECTION, encoding="utf-8")

    after = PREREG.read_bytes()
    txt = after.decode("utf-8")
    ok = after[:len(before)] == before
    print("=== 追加结果 ===")
    print(f"  原文 {len(before):,} bytes / {n_before:,} 行 / sha256 {sha_before[:16]}")
    print(f"  现文 {len(after):,} bytes / {txt.count(chr(10)):,} 行")
    print(f"  ⚠ 原文逐字节未变：{ok}")
    print(f"  ⚠ 以换行结尾：{after.endswith(bytes([10]))}")
    print(f"  ⚠ 坏字（原始字节层）：{txt.count(chr(0xFFFD))}")
    print(f"  ⚠ 修订 167 段仍在：{'## 修订 167 ' in txt}")
    print(f"  ⚠ 修订 168 段已在：{'## 修订 168 ' in txt}")
    if not ok or "## 修订 168 " not in txt:
        print("[错误] 追加未生效 —— 不许当成成功")
        raise SystemExit(2)


if __name__ == "__main__":
    main()